@startuml

enum PriorityScore {
  HIGH
  LOW
}

class HospitalHouseMD {
  + Name : string
}

class Patient {
  + Name : string
}

class Doctor {
  + Name : string
}

class Nurse {
  + Name : string
}

class Illness {
  + Name : string
  + PriorityScore : PriorityScore
}

class Diagnosis {
  + Description : string
}

class Treatment {
  + Stage : int
}

class ConsentForm {
  + IsSigned : boolean
}

HospitalHouseMD "1" -- "*" Patient
HospitalHouseMD "1" -- "*" Doctor
HospitalHouseMD "1" -- "*" Nurse
HospitalHouseMD "1" -- "*" Illness

Patient "1" -- "*" Diagnosis : has
Doctor "1..*" -- "*" Diagnosis : makes
Doctor "1" -- "1" HospitalHouseMD : head doctor

Diagnosis "1" -- "*" Treatment : results in
Illness "1" -- "*" Diagnosis : causes
Illness "1" -- "*" Treatment : has possible

Patient "1" -- "0..1" ConsentForm : signs
Treatment "0..*" -- "0..1" ConsentForm : requires

Doctor "1" -- "*" Treatment : downgrades
Nurse "1..*" -- "*" Treatment : checks
Doctor "1..*" -- "*" Treatment : checks

@enduml

